$ErrorActionPreference='Stop';$Timeout=30000;$ws=$null;$sid=$null;$next=0
function C([string]$m,$p=@{},[string]$s=$null){$script:next++;$o=[ordered]@{id=$script:next;method=$m;params=$p};if($s){$o.sessionId=$s};$b=[Text.Encoding]::UTF8.GetBytes(($o|ConvertTo-Json -Compress -Depth 20));$cts=[Threading.CancellationTokenSource]::new($Timeout);$ws.SendAsync([ArraySegment[byte]]::new($b),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult();while($true){$buf=New-Object byte[] 65536;$r=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult();$x=([Text.Encoding]::UTF8.GetString($buf,0,$r.Count)|ConvertFrom-Json);if($x.id -eq $script:next){if($x.error){throw $x.error.message};return $x}}}
$v=Invoke-RestMethod http://127.0.0.1:9224/json/version;$ws=[Net.WebSockets.ClientWebSocket]::new();$ws.ConnectAsync([Uri]$v.webSocketDebuggerUrl,([Threading.CancellationTokenSource]::new($Timeout)).Token).GetAwaiter().GetResult();$ti=C 'Target.getTargets';$t=@($ti.result.targetInfos)|?{$_.type -eq 'page' -and $_.url -like 'http://127.0.0.1:8080/*'}|select -First 1;if(!$t){throw 'Open WebUI target absent'};$sid=(C 'Target.attachToTarget' @{targetId=$t.targetId;flatten=$true}).result.sessionId;[void](C 'Runtime.enable' @{} $sid)
$expr='(()=>({url:location.href,body:(document.body?.innerText||"").slice(0,2500),buttons:[...document.querySelectorAll("button")].map(x=>(x.innerText||x.getAttribute("aria-label")||"").trim()).filter(Boolean).slice(0,40)}))()'
$raw=C 'Runtime.evaluate' @{returnByValue=$true;awaitPromise=$true;expression=$expr} $sid;$raw|ConvertTo-Json -Depth 10 -Compress
